with a as(select * from public.authors where open_library_id=any(array['OL22258A','OL8102042A','OL527373A','OL610278A','OL30401A','OL25149A','OL51237A','OL55234A','OL57758A','OL1213378A','OL124338A','OL1615731A','OL431450A','OL7506979A','OL7386651A','OL7459357A']::text[]) or id=any(array[342,2617,968,3175,636,638,887,654,637,707,3346,1533,341]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789022598115','9789022835777','9789027472113','9789041406439','9789041761316','9789074336994','9789010053220','9789029518703','9789028200739','9789023433729','9789062130825','9789023993254','9789026350856']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL25346692W','OL3236099W','OL3600817W','OL486654W','OL48903W','OL659053W','OL699573W','OL719954W','OL109949W','OL11780431W','OL1232226W','OL20448029W','OL21216675W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['deathoftheblackwidow','jeugdzonde','hetdenkendehartvandebarak','nightwork','turnodenoche','nachtwerk','landoftheliving','debewoondewereld','theriverking','onderwater','hettheaterdebriefendewaarheid','destillevriend','ikhadeenwapenbroeder','degoddenkbaardenkbaardegod','madelonindemistvanhetschimmenrijk','indemistvanhetschimmenrijk','zwijgenkannietverbeterdworden','diezeitdesskorpions','dewoestijnloper','theunderstudy','deunderstudy']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['deathoftheblackwidow','jeugdzonde','hetdenkendehartvandebarak','nightwork','turnodenoche','nachtwerk','landoftheliving','debewoondewereld','theriverking','onderwater','hettheaterdebriefendewaarheid','destillevriend','ikhadeenwapenbroeder','degoddenkbaardenkbaardegod','madelonindemistvanhetschimmenrijk','indemistvanhetschimmenrijk','zwijgenkannietverbeterdworden','diezeitdesskorpions','dewoestijnloper','theunderstudy','deunderstudy']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987137001 and 987137999),'editions',(select count(*) from public.editions where id between 987237001 and 987237999),'authors',(select count(*) from public.authors where id between 987337001 and 987337999))) as preflight;
